import"./strings.m.js";import"./policy_precedence_row.js";import"./policy_row.js";import{CustomElement}from"chrome://resources/js/custom_element.js";import{getRequiredElement}from"chrome://resources/js/util.js";import{getTemplate}from"./policy_table.html.js";export class PolicyTableElement extends CustomElement{static get template(){return getTemplate()}filterPattern="";update(dataModel){const mainContent=this.getRequiredElement(".main");const policies=this.shadowRoot.querySelectorAll(".policy-data");this.getRequiredElement(".header").textContent=dataModel.name;this.getRequiredElement(".id").textContent=dataModel.id||null;this.getRequiredElement(".id").hidden=!dataModel.id;policies.forEach((row=>mainContent.removeChild(row)));dataModel.policies.sort(((a,b)=>{if(a.value!==undefined&&b.value!==undefined||a.value===b.value){if(a.link!==undefined&&b.link!==undefined){return a.name>b.name?1:-1}return a.link!==undefined?-1:1}return a.value!==undefined?-1:1})).forEach((policy=>{const policyRow=document.createElement("policy-row");policyRow.initialize(policy);mainContent.appendChild(policyRow)}));this.filter();if(dataModel.name==="Policy Precedence"){const precedenceRowOld=this.shadowRoot.querySelectorAll(".policy-precedence-data");precedenceRowOld.forEach((row=>mainContent.removeChild(row)));if(dataModel.precedenceOrder!=undefined){const precedenceRow=document.createElement("policy-precedence-row");precedenceRow.initialize(dataModel.precedenceOrder);mainContent.appendChild(precedenceRow)}}}setFilterPattern(pattern){this.filterPattern=pattern.toLowerCase();this.filter()}filter(){const showUnset=getRequiredElement("show-unset").checked;const policies=this.shadowRoot.querySelectorAll(".policy-data");for(let i=0;i<policies.length;i++){const policyDisplay=policies[i];policyDisplay.hidden=policyDisplay.policy.value===undefined&&!showUnset||policyDisplay.policy.name.toLowerCase().indexOf(this.filterPattern)===-1}this.getRequiredElement(".no-policy").hidden=!!this.shadowRoot.querySelector(".policy-data:not([hidden])")}}customElements.define("policy-table",PolicyTableElement);